            for t in toks:
                if t.type == tokenize.COMMENT and 'TODO' in t.string:
                    results.append((rel, t.start[0]))
        except Exception as e:
            # fallback: naive scan per line using tokenize on each line won't help;
            # just report nothing but print error
            print('ERROR', rel, e, file=sys.stderr)

results.sort(key=lambda x: (x[0], x[1]))
with open('todos.txt', 'w', encoding='utf-8') as f:
    for p, ln in results:
        f.write(f'{p}:{ln}\n')
print('wrote', len(results), 'entries')
